use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut lefts: Vec<int> = []
    let mut rights: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut arg: int = 0
        if parts.len() > 1 {
            arg = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if root == -1 {
                keys.push(arg)
                lefts.push(-1)
                rights.push(-1)
                root = 0
                println("ok")
            } else {
                let mut cur: int = root
                let mut done = false
                while !done {
                    if keys[cur] == arg {
                        println("dup")
                        done = true
                    } else if arg < keys[cur] {
                        if lefts[cur] == -1 {
                            let idx: int = keys.len()
                            keys.push(arg)
                            lefts.push(-1)
                            rights.push(-1)
                            lefts[cur] = idx
                            println("ok")
                            done = true
                        } else {
                            cur = lefts[cur]
                        }
                    } else {
                        if rights[cur] == -1 {
                            let idx: int = keys.len()
                            keys.push(arg)
                            lefts.push(-1)
                            rights.push(-1)
                            rights[cur] = idx
                            println("ok")
                            done = true
                        } else {
                            cur = rights[cur]
                        }
                    }
                }
            }
        } else if cmd == "contains" {
            let mut cur: int = root
            let mut found = false
            while cur != -1 && !found {
                if keys[cur] == arg {
                    found = true
                } else if arg < keys[cur] {
                    cur = lefts[cur]
                } else {
                    cur = rights[cur]
                }
            }
            if found {
                println("yes")
            } else {
                println("no")
            }
        } else if cmd == "delete" {
            let mut cur: int = root
            let mut parent: int = -1
            let mut found = false
            while cur != -1 && !found {
                if keys[cur] == arg {
                    found = true
                } else {
                    parent = cur
                    if arg < keys[cur] {
                        cur = lefts[cur]
                    } else {
                        cur = rights[cur]
                    }
                }
            }
            if !found {
                println("missing")
            } else {
                if lefts[cur] != -1 && rights[cur] != -1 {
                    let mut sp: int = cur
                    let mut s: int = rights[cur]
                    while lefts[s] != -1 {
                        sp = s
                        s = lefts[s]
                    }
                    keys[cur] = keys[s]
                    let sr: int = rights[s]
                    if sp == cur {
                        rights[sp] = sr
                    } else {
                        lefts[sp] = sr
                    }
                } else {
                    let mut child: int = lefts[cur]
                    if child == -1 {
                        child = rights[cur]
                    }
                    if parent == -1 {
                        root = child
                    } else if lefts[parent] == cur {
                        lefts[parent] = child
                    } else {
                        rights[parent] = child
                    }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            if root == -1 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                let mut stack: Vec<int> = []
                let mut cur: int = root
                while cur != -1 || stack.len() > 0 {
                    while cur != -1 {
                        stack.push(cur)
                        cur = lefts[cur]
                    }
                    let n: int = stack.pop().unwrap_or(-1)
                    out.push("${keys[n]}")
                    cur = rights[n]
                }
                println(out.join(" "))
            }
        } else if cmd == "height" {
            let mut best: int = 0
            if root != -1 {
                let mut ns: Vec<int> = [root]
                let mut ds: Vec<int> = [1]
                while ns.len() > 0 {
                    let n: int = ns.pop().unwrap_or(-1)
                    let d: int = ds.pop().unwrap_or(0)
                    if d > best {
                        best = d
                    }
                    if lefts[n] != -1 {
                        ns.push(lefts[n])
                        ds.push(d + 1)
                    }
                    if rights[n] != -1 {
                        ns.push(rights[n])
                        ds.push(d + 1)
                    }
                }
            }
            println("${best}")
        } else if cmd == "min" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur: int = root
                while lefts[cur] != -1 {
                    cur = lefts[cur]
                }
                println("${keys[cur]}")
            }
        } else if cmd == "max" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur: int = root
                while rights[cur] != -1 {
                    cur = rights[cur]
                }
                println("${keys[cur]}")
            }
        }
    }
}

